import{_ as t,c as e,o as d,V as o}from"./chunks/framework.B6I5AJO8.js";const m=JSON.parse('{"title":"nb01 · Corpus discovery","description":"","frontmatter":{},"headers":[],"relativePath":"research/corpus-discovery.md","filePath":"research/corpus-discovery.md"}'),s={name:"research/corpus-discovery.md"},r=o('<h1 id="nb01-·-corpus-discovery" tabindex="-1">nb01 · Corpus discovery <a class="header-anchor" href="#nb01-·-corpus-discovery" aria-label="Permalink to &quot;nb01 · Corpus discovery&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb01_corpus_discovery.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>Before anything can be chunked or embedded, we need to know <strong>what is actually in the corpus</strong>: which files exist, which are worth indexing, and how each kind of content should be handled. nb01 scans the Kalisio repositories, inventories every file, and provides the later notebooks with a concrete per-content-type plan.</p><p>It reads sibling repos — <code>kdk</code>, <code>kano</code>, <code>crisis</code>, <code>kapp</code>, <code>skeleton</code>, <code>dok</code> — symlinked under <code>data/</code> (<code>bash scripts/setup_notebook_data.sh</code>). KDK is used as the primary corpus throughout.</p><h2 id="how-the-corpus-was-explored" tabindex="-1">How the corpus was explored <a class="header-anchor" href="#how-the-corpus-was-explored" aria-label="Permalink to &quot;How the corpus was explored&quot;">​</a></h2><p>Eight passes: full scan → exclusion → zones → content families → documentation deep-dive → JSON deep-dive → source-code signals → summary &amp; decisions.</p><h2 id="_1-scan-and-exclusion" tabindex="-1">1. Scan and exclusion <a class="header-anchor" href="#_1-scan-and-exclusion" aria-label="Permalink to &quot;1. Scan and exclusion&quot;">​</a></h2><p>The raw scan of KDK found <strong>976 files (32.8 MB)</strong> across 25 extensions. Excluding files with no semantic value for RAG — lock files, binary images (<code>.png</code>/<code>.svg</code>/<code>.tif</code>), auto-generated changelogs, minified data — removed <strong>118 files (21.8 MB)</strong>, leaving <strong>858 files (11.0 MB)</strong>.</p><p>By size the retained corpus consists mainly of <code>.js</code> (362 files, 1.9 MB), <code>.vue</code> (242, 835 KB), <code>.json</code> (26, 3.5 MB) and <code>.md</code> (142, 504 KB).</p><h2 id="_2-distribution-by-zone" tabindex="-1">2. Distribution by zone <a class="header-anchor" href="#_2-distribution-by-zone" aria-label="Permalink to &quot;2. Distribution by zone&quot;">​</a></h2><table><thead><tr><th>Zone</th><th>Files</th><th>Size</th><th>Top extensions</th></tr></thead><tbody><tr><td>core</td><td>305</td><td>921 KB</td><td>.vue 150, .js 149</td></tr><tr><td>map</td><td>238</td><td>1.3 MB</td><td>.js 142, .vue 87</td></tr><tr><td>docs</td><td>167</td><td>3.5 MB</td><td>.md 139, .xml 15, .drawio 8</td></tr><tr><td>test</td><td>50</td><td>4.6 MB</td><td>.js 21, .json 10, .ejs 9</td></tr><tr><td>extras</td><td>37</td><td>580 KB</td><td>.js 19, .mjs 17</td></tr><tr><td>vite</td><td>29</td><td>74 KB</td><td>.js 18, .vue 5</td></tr><tr><td>(root)</td><td>23</td><td>11 KB</td><td>.js 12</td></tr><tr><td>scripts</td><td>9</td><td>72 KB</td><td>.sh 6</td></tr></tbody></table><h2 id="_3-content-families" tabindex="-1">3. Content families <a class="header-anchor" href="#_3-content-families" aria-label="Permalink to &quot;3. Content families&quot;">​</a></h2><p>Ten families emerged, each needing a different chunking approach:</p><table><thead><tr><th>Family</th><th>Files</th><th>Size</th></tr></thead><tbody><tr><td>code_js</td><td>320</td><td>1.8 MB</td></tr><tr><td>vue_sfc</td><td>242</td><td>835 KB</td></tr><tr><td>documentation_markdown</td><td>139</td><td>496 KB</td></tr><tr><td>tests</td><td>47</td><td>4.6 MB</td></tr><tr><td>barrel_index_js</td><td>46</td><td>43 KB</td></tr><tr><td>diagrams_and_specs</td><td>23</td><td>3.0 MB</td></tr><tr><td>other</td><td>20</td><td>77 KB</td></tr><tr><td>json</td><td>16</td><td>173 KB</td></tr><tr><td>text_outside_docs</td><td>3</td><td>8 KB</td></tr><tr><td>templates</td><td>2</td><td>4 KB</td></tr></tbody></table><h2 id="_4-documentation-deep-dive-docs" tabindex="-1">4. Documentation deep-dive (<code>docs/</code>) <a class="header-anchor" href="#_4-documentation-deep-dive-docs" aria-label="Permalink to &quot;4. Documentation deep-dive (`docs/`)&quot;">​</a></h2><p>139 Markdown files, <strong>~126,710 tokens</strong>. The API reference accounts for the majority (116 files, ~116k tokens).</p><p><strong>Heading hierarchy</strong> — 1,245 sections across the files: 137 H1, <strong>504 H2</strong>, <strong>524 H3</strong>, 80 H4. The roughly equal H2/H3 counts are why the chunking strategy splits at <code>##</code> and re-splits at <code>###</code>.</p><p><strong>H2-level chunking simulation</strong> — splitting every doc at <code>##</code> yields <strong>642 chunks</strong> (median 72, mean 196 tokens). But <strong>211 are too small</strong> (&lt;50 tokens → merge candidates) and <strong>10 are too large</strong> (&gt;1500 tokens → H3 re-split candidates; the largest is &quot;Features service&quot; at 2,981 tokens in <code>api/map/services.md</code>). This directly motivates the merge-small / re-split-large rules in nb02.</p><p><strong>Special content</strong> — tables 737, internal links 262, code blocks 184, admonitions 152, images 44, mermaid 13. Code blocks and tables must survive chunking intact, which sets nb02&#39;s code-block-integrity requirement.</p><p><strong>Token budget</strong> — ~126,710 tokens ≈ 253 chunks at 500 tokens, ≈ 126 at 1000.</p><h2 id="_5-json-deep-dive" tabindex="-1">5. JSON deep-dive <a class="header-anchor" href="#_5-json-deep-dive" aria-label="Permalink to &quot;5. JSON deep-dive&quot;">​</a></h2><p>26 JSON files, 3.5 MB, but their RAG value varies widely:</p><table><thead><tr><th>Type</th><th>Files</th><th>Size</th><th>RAG priority</th></tr></thead><tbody><tr><td>schemas_validation</td><td>8</td><td>18 KB</td><td><strong>high</strong></td></tr><tr><td>i18n_translations</td><td>4</td><td>143 KB</td><td>medium</td></tr><tr><td>docs_meta</td><td>1</td><td>624 B</td><td>medium</td></tr><tr><td>test_fixtures</td><td>9</td><td>3.4 MB</td><td>low</td></tr><tr><td>test_config</td><td>1</td><td>1.3 KB</td><td>low</td></tr><tr><td>package_tooling</td><td>3</td><td>12 KB</td><td>exclude</td></tr></tbody></table><p>All JSON would cost ~927,649 tokens; keeping only high+medium priority costs ~41,031. <strong>Excluding test fixtures and tooling saves ~886,618 tokens</strong> for almost no loss of RAG value.</p><h2 id="_6-source-code-signals" tabindex="-1">6. Source-code signals <a class="header-anchor" href="#_6-source-code-signals" aria-label="Permalink to &quot;6. Source-code signals&quot;">​</a></h2><p><code>core</code> (305 files, 504 exports) and <code>map</code> (238 files, 512 exports) contain almost all the logic. A semantic-density scan (exports + functions + classes per file) identified the files with the most API surface — e.g. <code>map/client/utils/utils.layers.js</code> (31 exports, 46 functions, 713 lines) and <code>utils.features.js</code> (30 exports, 31 functions). These dense utility files require symbol-level splitting rather than size-based splitting, which nb03 addresses.</p><h2 id="decisions-carried-into-nb02" tabindex="-1">Decisions carried into nb02 <a class="header-anchor" href="#decisions-carried-into-nb02" aria-label="Permalink to &quot;Decisions carried into nb02&quot;">​</a></h2><ol><li><strong>Markdown</strong> — split at <code>##</code>, re-split oversized sections at <code>###</code>, merge tiny sections.</li><li><strong>JSON</strong> — include schemas and i18n; exclude test fixtures and <code>package.json</code>.</li><li><strong>JS / Vue</strong> — needs dedicated analysis (nb03); dense utility files require symbol-level splitting.</li><li><strong>Barrel files</strong> (<code>index.js</code>) — navigation/metadata only, not primary chunks.</li><li><strong>Test files</strong> — excluded from the initial index.</li></ol><h2 id="the-reusable-outcome" tabindex="-1">The reusable outcome <a class="header-anchor" href="#the-reusable-outcome" aria-label="Permalink to &quot;The reusable outcome&quot;">​</a></h2><p>The filtering logic was extracted into a generic corpus-filter module and run across <strong>every</strong> project under <code>data/</code>, not just KDK:</p><table><thead><tr><th>Project</th><th>Scanned</th><th>Included</th><th>Excluded</th></tr></thead><tbody><tr><td>kdk</td><td>976</td><td>821</td><td>155</td></tr><tr><td>kano</td><td>393</td><td>214</td><td>179</td></tr><tr><td>crisis</td><td>339</td><td>267</td><td>72</td></tr><tr><td>kapp</td><td>189</td><td>145</td><td>44</td></tr><tr><td>skeleton</td><td>133</td><td>88</td><td>45</td></tr></tbody></table><p>Across all projects the main exclusion reasons were binary/non-text (364), excluded filename (84), no extension (18) and file-too-large (15). This same module feeds the file-selection stage of the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>.</p>',33),n=[r];function i(a,c,l,h,u,p){return d(),e("div",null,n)}const b=t(s,[["render",i]]);export{m as __pageData,b as default};
